import type { HTMLAttributes } from "react";

type BadgeVariant = "default" | "outline" | "muted" | "danger";
export type BadgeProps = HTMLAttributes<HTMLSpanElement> & { variant?: BadgeVariant };
const variants: Record<BadgeVariant, string> = {
  default: "co-bg-black co-text-white",
  outline: "co-border co-border-black/20 co-bg-white co-text-black",
  muted: "co-bg-black/5 co-text-black",
  danger: "co-bg-black co-text-white co-ring-2 co-ring-black/20",
};

export function Badge({ className = "", variant = "default", ...props }: BadgeProps) {
  return <span className={`co-inline-flex co-items-center co-rounded-full co-px-2.5 co-py-1 co-text-xs co-font-medium ${variants[variant]} ${className}`.trim()} {...props} />;
}
